// Flags every published workflow that has no error workflow configured.
// Read-only: this workflow never writes back to the n8n API.
// Mode: Run Once for All Items

const config = $('Set Workflow Parameters').first().json;

const excludedTags = String(config.excludedTags || '')
  .split(',')
  .map((tag) => tag.trim().toLowerCase())
  .filter(Boolean);

const excludedIds = String(config.excludedWorkflowIds || '')
  .split(',')
  .map((id) => id.trim())
  .filter(Boolean);

const results = [];

for (const item of $input.all()) {
  const workflow = item.json;

  // Safety net: the API filter should already exclude drafts, but the
  // parameter name has changed across n8n versions, so re-check here.
  if (workflow.active !== true) continue;
  if (workflow.isArchived === true) continue;

  const tags = (workflow.tags || []).map((tag) =>
    (typeof tag === 'string' ? tag : tag.name || '').toLowerCase(),
  );

  // A workflow containing an Error Trigger is itself an error handler.
  const isErrorHandler = (workflow.nodes || []).some(
    (node) => node.type === 'n8n-nodes-base.errorTrigger',
  );
  if (isErrorHandler) continue;

  if (tags.some((tag) => excludedTags.includes(tag))) continue;
  if (excludedIds.includes(String(workflow.id))) continue;

  const errorWorkflow = (workflow.settings || {}).errorWorkflow || null;
  if (errorWorkflow) continue;

  results.push({
    json: {
      id: workflow.id,
      name: workflow.name,
      tags,
      updatedAt: workflow.updatedAt || null,
    },
  });
}

// Most recently updated first: those are the ones worth fixing now.
results.sort((a, b) =>
  String(b.json.updatedAt || '').localeCompare(String(a.json.updatedAt || '')),
);

return results;

// Formats the audit result as Slack mrkdwn.
// Mode: Run Once for All Items

const config = $('Set Workflow Parameters').first().json;
const baseUrl = String(config.n8nBaseUrl || '').replace(/\/+$/, '');
const maxListed = Number(config.maxWorkflowsListed) || 25;

const scanned = $('Fetch All Published Workflows').all().length;
const unprotected = $input.all().map((item) => item.json);

// The IF node downstream reads this count.
if (unprotected.length === 0) {
  return [{ json: { unprotectedCount: 0, scannedCount: scanned, message: '' } }];
}

const link = (workflow) =>
  baseUrl
    ? `<${baseUrl}/workflow/${workflow.id}|${workflow.name}>`
    : `${workflow.name} (${workflow.id})`;

const lines = [
  `:shield: *Error workflow audit* — ${unprotected.length} of ${scanned} published workflows have no error workflow configured.`,
  '',
];

for (const workflow of unprotected.slice(0, maxListed)) {
  lines.push(`• ${link(workflow)}`);
}

if (unprotected.length > maxListed) {
  lines.push(`• _…and ${unprotected.length - maxListed} more_`);
}

lines.push('');
lines.push('_Fix: open the workflow → Options → Settings → Error workflow._');

let message = lines.join('\n');
if (message.length > 2900) {
  message = `${message.slice(0, 2850)}\n_…truncated_`;
}

return [
  {
    json: {
      message,
      unprotectedCount: unprotected.length,
      scannedCount: scanned,
      workflows: unprotected,
    },
  },
];
